'use strict';

// MODULES //

var tape = require( 'tape' );
var validate = require( './../lib/validate.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof validate, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an error if not provided an object', function test( t ) {
	var values;
	var err;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		null,
		void 0,
		[],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		err = validate( {}, values[ i ] );
		t.ok( err instanceof TypeError, 'returns a type error when provided '+values[i] );
	}
	t.end();
});

tape( 'the function returns an error if provided an invalid `alpha` option', function test( t ) {
	var values;
	var err;
	var i;

	values = [
		'5',
		-0.1,
		1.5,
		NaN,
		true,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		err = validate( {}, {
			'alpha': values[ i ]
		});
		t.ok( err instanceof TypeError, 'returns a type error when provided '+values[i] );
	}
	t.end();
});

tape( 'the function returns an error if provided an invalid `alternative` option', function test( t ) {
	var values;
	var err;
	var i;

	values = [
		'abc',
		'not-valid',
		''
	];

	for ( i = 0; i < values.length; i++ ) {
		err = validate( {}, {
			'alternative': values[ i ]
		});
		t.ok( err instanceof TypeError, 'returns a type error when provided '+values[i] );
	}
	t.end();
});

tape( 'the function returns an error if provided an invalid `rho` option', function test( t ) {
	var values;
	var err;
	var i;

	values = [
		'5',
		-1.5,
		1.5,
		NaN,
		true,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		err = validate( {}, {
			'rho': values[ i ]
		});
		t.ok( err instanceof TypeError, 'returns a type error when provided '+values[i] );
	}
	t.end();
});

tape( 'the function returns `null` if all options are valid', function test( t ) {
	var err;

	err = validate( {}, {
		'alpha': 0.01,
		'alternative': 'greater',
		'rho': 0.5
	});
	t.strictEqual( err, null, 'returns null' );
	t.end();
});
